// 1. Ambil raw text dari balasan Groq
let rawText = $input.first().json.choices[0].message.content;

try {
    // 2. Trik Ninja: Cari HANYA teks dari kurung kurawal pembuka { sampai penutup }
    // Ini otomatis mengabaikan teks basa-basi AI atau tanda markdown (```json)
    let jsonMatch = rawText.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
        // 3. Ubah teks murni tersebut menjadi Objek JSON sungguhan
        let finalData = JSON.parse(jsonMatch[0]);

        // 4. Lemparkan ke n8n dalam format yang valid
        return [{
            json: finalData
        }];
    } else {
        // Jika AI sama sekali tidak mengeluarkan kurung kurawal
        return [{
            json: { "error": "Format JSON tidak ditemukan", "balasan_mentah": rawText }
        }];
    }
} catch (error) {
    // Jika format JSON-nya cacat (kurang tanda kutip, koma berlebih, dll)
    return [{
        json: { "error": "Gagal membaca JSON", "detail": error.message, "balasan_mentah": rawText }
    }];
}

